int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

int get_ans(int x, int k){
    if(x == 1) return 0;
    vector<int> divs;
    for(int i = 1; i * i <= x; i++){
        if(x % i == 0){
            divs.push_back(i);
            divs.push_back(x / i);
        }
    }
    sort(all(divs));
    int n = divs.size();
    vector<int> dp(n, 100);
    dp[0] = 0;
    for(int i = 1; i < n; i++){
        for(int j = i - 1; j >= 0; j--){
            if(divs[i] / divs[j] > k){
                break;
            }
            if(divs[i] % divs[j] == 0) {
                dp[i] = min(dp[i], dp[j] + 1);
            }
        }
    }
    return dp[n - 1] == 100 ? -1 : dp[n - 1];
}

void solve(int tc){
    int x, y, k;
    cin >> x >> y >> k;
    int g = gcd(x, y);
    x /= g;
    y /= g;
    int ax = get_ans(x, k);
    int ay = get_ans(y, k);
    if(ax == -1 || ay == -1) cout << -1;
    else cout << ax + ay;
}

