int max_op(int a, int b) {
    int min_part = a;
    while (min_part % 2 == 0 && min_part / 2 != b) {
        min_part /= 2;
    }
    if (min_part % 2 == 1) {
        return a / min_part;
    }
    int true_min = min_part;
    while (true_min % 2 == 0) {
        true_min /= 2;
    }
    return 1 + (a - min_part) / true_min;
}

void solve(int tc){
    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    for (int &e: a) cin >> e;
    vector<int> pre(n, 0);
    for (int j = 1; j < n; ++j) {
        pre[j] = pre[j - 1] + max_op(a[j - 1], a[j]);
    }
    vector<int> suf(n, 0);
    for (int j = n - 2; j >= 0; --j) {
        suf[j] = suf[j + 1] + max_op(a[j + 1], a[j]);
    }
    for (int i = 0; i < n; i++) {
        int res = max_op(a[i], 0) + pre[i] + suf[i];
        if (res >= k) {
            cout << "YES";
            return;
        }
    }
    cout << "NO";
}

